INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Client-Betriebssystem immer notwendig für Anwendungen?', 2, '[{"text": "Ja", "correct": true, "because": "Grundlage für Softwareausführung"}, {"text": "Nein", "correct": false, "because": "Selten ohne BS"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Betriebssystem wähle ich für einfache Büroanwendungen?', 3, '[{"text": "Windows", "correct": true, "because": "Breite Kompatibilität mit Office"}, {"text": "Linux", "correct": false, "because": "Weniger Standardsoftware"}, {"text": "Server-BS", "correct": false, "because": "Nicht für Clients geeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen eine Anwendung für Thin Clients geeignet?', 5, '[{"text": "Serverbasierte Ausführung", "correct": true, "because": "Thin Clients verarbeiten wenig"}, {"text": "Geringer Ressourcenbedarf", "correct": true, "because": "Minimaler Client-Footprint"}, {"text": "Hohe Grafikleistung", "correct": false, "because": "Serverabhängig"}, {"text": "Lokale Installation", "correct": false, "because": "Nicht typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Client-BS unterstützt lokale Apps. b) Anwendungen laufen ohne BS.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, BS erforderlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Softwarewahl für eine Workstation?', 4, '[{"text": "Kompatibilität mit BS", "correct": false, "because": "Muss passen"}, {"text": "Leistungsanforderungen", "correct": false, "because": "Entscheidend für Nutzung"}, {"text": "Serveroptimierung", "correct": true, "because": "Irrelevant für Client"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Linux als Client-BS für Spiele geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Weniger Spieleunterstützung"}, {"text": "Ja", "correct": false, "because": "Windows dominiert Gaming"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature priorisiere ich für eine CAD-Anwendung?', 3, '[{"text": "Hohe Kompatibilität", "correct": true, "because": "Spezifische Hardware nötig"}, {"text": "Geringer Preis", "correct": false, "because": "Leistung zählt mehr"}, {"text": "Einfache Bedienung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Client-BS wie Windows?', 5, '[{"text": "Breite Softwareunterstützung", "correct": true, "because": "Viele Anwendungen laufen"}, {"text": "Benutzerfreundlichkeit", "correct": true, "because": "Intuitive Oberfläche"}, {"text": "Kostenfreiheit", "correct": false, "because": "Lizenzkosten üblich"}, {"text": "Serverfunktionen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Anwendungen brauchen spezifische BS-Versionen. b) Client-BS ist immer teuer. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, z.B. Linux kostenlos"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Software auf einem Thin Client?', 4, '[{"text": "Netzwerkverbindung", "correct": false, "because": "Serverzugriff nötig"}, {"text": "Kompatibilität mit BS", "correct": false, "because": "Muss passen"}, {"text": "Hohe lokale Leistung", "correct": true, "because": "Server übernimmt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt jedes Client-BS alle Anwendungen?', 2, '[{"text": "Nein", "correct": true, "because": "Kompatibilität variiert"}, {"text": "Ja", "correct": false, "because": "Einschränkungen üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für eine Büroanwendung wichtig?', 4, '[{"text": "Einfache Bedienung", "correct": true, "because": "Effizienz für Nutzer"}, {"text": "Kompatibilität mit Client-BS", "correct": true, "because": "Muss laufen"}, {"text": "Hohe Serverlast", "correct": false, "because": "Lokal ausführbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Anwendungen auf Thin Clients nicht lokal laufen. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Server übernimmt Verarbeitung"}, {"text": "Nein", "correct": false, "because": "Minimal lokal möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für ein Client-BS auf einer Workstation?', 3, '[{"text": "Leistungsunterstützung", "correct": true, "because": "Maximale Hardware nutzen"}, {"text": "Geringer Ressourcenbedarf", "correct": false, "because": "Nicht primär"}, {"text": "Serverkonnektivität", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Client-BS verwaltet lokale Ressourcen. b) Anwendungen brauchen keine Updates.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Updates nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein Client-BS wie Linux?', 5, '[{"text": "Geringere Softwareauswahl", "correct": true, "because": "Weniger proprietäre Apps"}, {"text": "Lernkurve", "correct": true, "because": "Weniger intuitiv für Anfänger"}, {"text": "Hohe Kosten", "correct": false, "because": "Meist kostenlos"}, {"text": "Schlechte Leistung", "correct": false, "because": "Leistung gut"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Anwendung für Remote-Desktop unwichtig?', 3, '[{"text": "Netzwerkkonnektivität", "correct": false, "because": "Kern der Funktion"}, {"text": "Kompatibilität mit BS", "correct": false, "because": "Muss passen"}, {"text": "Lokale Grafikleistung", "correct": true, "because": "Server übernimmt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Windows als Client-BS für Serverdienste geeignet?', 3, '[{"text": "Nein", "correct": true, "because": "Client-Fokus, nicht Server"}, {"text": "Ja", "correct": false, "because": "Begrenzt möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Anwendungen ohne Client-BS laufen?', 2, '[{"text": "Nein", "correct": true, "because": "BS als Basis nötig"}, {"text": "Ja", "correct": false, "because": "Selten ohne BS"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Client-BS wähle ich für Multimedia-Bearbeitung?', 4, '[{"text": "Windows", "correct": true, "because": "Breite Softwareunterstützung"}, {"text": "Linux", "correct": false, "because": "Weniger Multimedia-Tools"}, {"text": "Thin-Client-BS", "correct": false, "because": "Serverabhängig"}]');
